import{_ as l,o as r,c as t,a5 as i}from"./chunks/framework.QnCkLuYX.js";const n="/assets/subtitle-mapping.DIZguqmF.png",c=JSON.parse('{"title":"导入素材","description":"","frontmatter":{},"headers":[],"relativePath":"02-importing-resources.md","filePath":"zh-CN/02-importing-resources.md"}'),s={name:"02-importing-resources.md"};function a(e,o,g,h,p,d){return r(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="导入素材" tabindex="-1">导入素材 <a class="header-anchor" href="#导入素材" aria-label="Permalink to &quot;导入素材&quot;">​</a></h1><p>导入原文、译文和视频，并确认每个文件对应的集数。</p><h2 id="你可以在本页完成什么" tabindex="-1">你可以在本页完成什么 <a class="header-anchor" href="#你可以在本页完成什么" aria-label="Permalink to &quot;你可以在本页完成什么&quot;">​</a></h2><ul><li>分别导入原文字幕、译文字幕和视频。</li><li>检查自动识别的集数，并修正无法识别或冲突的文件。</li><li>设置项目质量标准和目标语言。</li><li>在已有项目中补充、更新或替换素材。</li></ul><h2 id="创建项目文件夹" tabindex="-1">创建项目文件夹 <a class="header-anchor" href="#创建项目文件夹" aria-label="Permalink to &quot;创建项目文件夹&quot;">​</a></h2><p>点击 <strong>新建项目</strong> 后选择一个项目文件夹。GridSubStudio 会在其中创建项目配置和字幕工作区。建议：</p><ul><li>每个字幕项目使用独立文件夹。</li><li>不要把两个剧集项目共用同一个项目文件夹。</li><li>原始字幕和视频可以位于项目文件夹外；项目会保存它们的引用。</li><li>项目运行期间不要手动编辑 <code>project.json</code> 或草稿文件。</li></ul><h2 id="导入原文字幕" tabindex="-1">导入原文字幕 <a class="header-anchor" href="#导入原文字幕" aria-label="Permalink to &quot;导入原文字幕&quot;">​</a></h2><ol><li>在项目设置的 <strong>导入</strong> 页点击 <strong>导入原文</strong>。</li><li>选择一个或多个 SRT、ASS 或 SSA 文件。</li><li>等待状态从“正在导入”变为“等待确认”或“就绪”。</li><li>打开 <strong>字幕文件名映射</strong>，在 <strong>原文</strong> 标签中检查结果。</li></ol><p>原文字幕会填入工作区的原文字段。ASS/SSA 文件中的样式头会保存为后续 ASS 导出的源模板。</p><h2 id="导入译文字幕" tabindex="-1">导入译文字幕 <a class="header-anchor" href="#导入译文字幕" aria-label="Permalink to &quot;导入译文字幕&quot;">​</a></h2><ol><li>在 <strong>导入</strong> 页点击 <strong>导入译文</strong>。</li><li>选择译文字幕文件。</li><li>在 <strong>字幕文件名映射 → 译文</strong> 中检查集数。</li></ol><p>译文字幕会填入译文字段。同一集可以同时拥有一份原文字幕和一份译文字幕；它们属于不同轨道，不会因为集数相同而被判为重复。</p><p>如果已有原文，译文导入会按集数和时间对齐。无法安全对齐时，应用会要求先审查差异。</p><h2 id="导入视频" tabindex="-1">导入视频 <a class="header-anchor" href="#导入视频" aria-label="Permalink to &quot;导入视频&quot;">​</a></h2><ol><li>点击 <strong>导入视频</strong>。</li><li>选择视频文件。</li><li>在 <strong>视频文件名映射</strong> 中检查集数和匹配结果。</li></ol><p>视频是可选资源。没有视频仍可建立项目和编辑字幕，但无法进行同步播放和时间轴预览。</p><h2 id="检查和修正集数" tabindex="-1">检查和修正集数 <a class="header-anchor" href="#检查和修正集数" aria-label="Permalink to &quot;检查和修正集数&quot;">​</a></h2><p><img src="'+n+'" alt="项目设置中的字幕文件名映射，显示文件、集数和检查状态"></p><p>映射页会显示文件名、识别出的集数和检查状态：</p><ul><li><strong>就绪</strong>：识别结果明确，可以直接使用。</li><li><strong>检查分集</strong>：已给出低置信候选，建议人工核对；只要集数合法且无冲突，它不会单独阻止确认。</li><li><strong>选择分集/无分集</strong>：无法确定集数，必须手动填写。</li><li><strong>冲突</strong>：同一类资源出现等价集数，例如 <code>4</code>、<code>04</code> 和 <code>004</code>；必须修正重复项。</li><li><strong>无匹配/缺少文件</strong>：资源不可用或视频匹配不明确，需要重新选择或修复。</li></ul><p>修正方法：</p><ol><li>点击集数单元格。</li><li>输入正确的数字集数。</li><li>按 <code>Enter</code> 或移开焦点提交。</li><li>检查整个列表是否产生新的冲突。</li></ol><p>手动输入会成为该资源的优先映射。以后重新打开项目或修复视频时，文件名推断不会覆盖它。</p><blockquote><p>字幕的原文和译文轨道分别检查重复；视频单独检查。低置信是复核提示，不等于导入错误。</p></blockquote><h2 id="处理无法识别或重复的文件" tabindex="-1">处理无法识别或重复的文件 <a class="header-anchor" href="#处理无法识别或重复的文件" aria-label="Permalink to &quot;处理无法识别或重复的文件&quot;">​</a></h2><ul><li><strong>文件名有年份、版本号或清晰度</strong>：不要假定任意数字都是集数，直接核对并手动填写。</li><li><strong>多个文件得到同一集数</strong>：检查是否选错文件、重复导入或输入了等价编号。</li><li><strong>视频有多个候选</strong>：在对应行选择正确匹配；无法确认时保留手动状态并重新选择视频。</li><li><strong>导入错误</strong>：查看映射行的错误标记，重新选择可读取的字幕文件。</li><li><strong>仍在导入</strong>：等待全部文件完成；导入进行中无法最终确认。</li></ul><h2 id="设置项目参数" tabindex="-1">设置项目参数 <a class="header-anchor" href="#设置项目参数" aria-label="Permalink to &quot;设置项目参数&quot;">​</a></h2><p>在 <strong>其他参数</strong> 页完成：</p><ul><li><strong>最大 CPS</strong>：用于标记阅读速度过高的字幕。</li><li><strong>行长</strong>：用于标记过长译文，并控制行工具的断行上限。</li><li><strong>目标语言</strong>：机器翻译任务的默认目标语言。</li><li><strong>拼写检查语言</strong>：选择已安装的词典；没有词典时可暂时留空。</li></ul><p>这些值属于当前项目。新项目会使用上次项目设置中的参数作为初始值，打开已有项目时不会覆盖已保存参数。</p><h2 id="确认导入结果" tabindex="-1">确认导入结果 <a class="header-anchor" href="#确认导入结果" aria-label="Permalink to &quot;确认导入结果&quot;">​</a></h2><ol><li>依次检查 <strong>导入</strong>、<strong>字幕文件名映射</strong>、<strong>视频文件名映射</strong> 和 <strong>其他参数</strong>。</li><li>确认没有未识别、冲突、缺失、无匹配或导入错误。</li><li>点击 <strong>确认</strong>。</li></ol><p>字幕在点击 <strong>确认</strong> 前只是待处理计划；确认后才写入项目。关闭带有待处理导入的项目设置时，应用会提示继续编辑、放弃或保存，避免静默丢失选择。</p><h2 id="补充或更换项目素材" tabindex="-1">补充或更换项目素材 <a class="header-anchor" href="#补充或更换项目素材" aria-label="Permalink to &quot;补充或更换项目素材&quot;">​</a></h2><p>在已有项目中点击顶部 <strong>项目设置</strong>，再次导入原文字幕、译文字幕或视频。重新导入字幕时，应用会要求选择 <strong>精确更新</strong> 或 <strong>整体替换</strong>，并在弹窗中简要说明两种模式。重新导入视频不需要选择模式：选择文件后，应用直接更新对应分集的视频，并保留其他分集的视频引用。</p><ul><li><p>字幕的 <strong>精确更新</strong>适合补集或修订个别分集。它以 <strong>字幕文件名映射</strong> 中最终确认的集数为准，而不是简单比较文件名。</p><ul><li>已存在的同集素材会由本次导入内容更新；本次没有导入的其他集保持不变。</li><li>本次包含项目中原本没有的集数时，新集会加入项目，并不要求必须先有“匹配”的旧集。</li><li>更新原文字幕时，导入分集的原文和行结构以新文件为准；能按时间和文本对齐的现有译文会保留。</li><li>更新译文字幕时，导入分集的译文以新文件为准；能按时间对齐的现有原文会保留。</li></ul></li><li><p>字幕的 <strong>整体替换</strong> 是“按分集整体替换”。它与 <strong>精确更新</strong> 使用相同的作用范围：都以最终确认的分集映射为准，并保留本次没有匹配到的其他分集。</p><ul><li>对每个匹配分集，应用先移除该集的全部旧字幕行和已登记字幕来源，再用新文件完整重建该集；不会尝试对齐新旧行，也不会保留该集的孤立行或另一轨道内容。</li><li>例如，只用新的第 2 集原文执行 <strong>整体替换</strong> 时，第 2 集的旧原文、旧译文和现有编辑都会被新文件取代；项目中的第 1、3 集保持不变。</li><li>如果本次映射到项目中原本没有的集数，该分集会作为新集加入。</li></ul></li><li><p>重新导入视频时，分集范围同样由最终确认的 <strong>视频文件名映射</strong> 决定。同集旧视频会被新视频替换；新集会加入；本次未匹配分集的视频保持不变。</p></li></ul><p>这些操作不会删除磁盘上的原始字幕或视频文件。字幕 <strong>整体替换</strong> 会清空原有撤销/重做历史，因此执行前应先保存项目并保留可恢复的副本。</p><p>字幕的 <strong>精确更新</strong> 不是按行号直接覆盖。应用会在导入分集内检查精确匹配、时间容差、拆分、合并和孤立行，并在需要时先显示审查窗口。确认审查结果后，返回项目设置检查映射，再点击 <strong>确认</strong> 才应用本批导入。详细说明见<a href="./07-saving-and-exporting.html#重新导入字幕">保存与导出</a>。同一批待确认字幕不能混用 <strong>精确更新</strong> 和 <strong>整体替换</strong>；需要改变模式时，应先完成或取消当前批次。</p><p>重新导入字幕或视频后，映射表会继续列出本次未受影响的既有文件，并同时显示本次新增或替换的文件。可在确认前检查完整分集覆盖；编辑 pending 字幕会更新当前导入计划，编辑既有字幕或视频会更新项目中对应的资源映射。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><ul><li><strong>确认按钮不可用</strong>：检查是否仍在导入，或是否有无集数、冲突、缺失和错误行。</li><li><strong>所有文件都显示需检查</strong>：逐项核对；合法的低置信结果不需要为了“变绿”而重复输入。</li><li><strong>视频缺失但项目能打开</strong>：打开项目不会因视频缺失而中止；进入项目设置确认前需要修复已知缺失资源。</li><li><strong>译文导入被阻止</strong>：通常是时间无法与已有原文安全对齐，请查看导入审查详情。</li></ul>',42)])])}const m=l(s,[["render",a]]);export{c as __pageData,m as default};
